def gen(rng):
    letters = 'abcdefghijklmnopqrstuvwxyz'
    def shift(w, k):
        return ''.join(letters[(ord(c) - 97 + k) % 26] for c in w)
    def fmt(ws):
        return str(len(ws)) + '\n' + '\n'.join(ws)
    def rnd(L, alpha=26):
        return ''.join(letters[rng.randrange(alpha)] for _ in range(L))
    tests = [fmt(['a']), fmt(['a', 'z', 'm']), fmt(['zz', 'aa', 'b', 'abb']), fmt(['abc', 'abc', 'abc']),
             fmt(['az', 'ba', 'cb', 'a', 'b']), fmt(['ab', 'ba', 'yz', 'za'])]
    for _ in range(14):
        k = rng.randint(1, 6)
        bases = [rnd(rng.randint(1, 5), rng.choice([2, 3, 26])) for _ in range(k)]
        ws = []
        for _ in range(rng.randint(2, 22)):
            ws.append(shift(rng.choice(bases), rng.randrange(26)))
        tests.append(fmt(ws))
    # large: short words, heavy collisions
    bases = [rnd(rng.randint(1, 5), 3) for _ in range(300)]
    ws = [shift(rng.choice(bases), rng.randrange(26)) for _ in range(100000)]
    tests.append(fmt(ws))
    # large: all random short words
    tests.append(fmt([rnd(rng.randint(1, 5)) for _ in range(100000)]))
    # medium length words, few groups
    bases = [rnd(500, 26) for _ in range(5)]
    tests.append(fmt([shift(rng.choice(bases), rng.randrange(26)) for _ in range(1000)]))
    # two huge strings that are buddies
    b = rnd(250000)
    tests.append(fmt([b, shift(b, 7)]))
    return tests
